const logger = winston.createLogger({ transports: [new winston.transports.File({ filename: 'error.log', level: 'error' })] });

Key: Always have global handlers. Log everything. Use process managers (PM2) to auto-restart on crashes.

git cherry-pick applies a specific commit from one branch onto another — without merging the entire branch.

// Scenario: You need one specific bug fix from develop branch on main
git checkout main
git cherry-pick abc1234  // Apply commit abc1234 onto main

// Cherry-pick multiple commits
git cherry-pick abc1234 def5678

// Cherry-pick a range
git cherry-pick abc1234..xyz9999

// If conflicts arise
git cherry-pick abc1234
// Fix conflicts in files
git add .
git cherry-pick --continue

// Abort cherry-pick
git cherry-pick --abort

Use cases: (1) Apply hotfix from develop to main (2) Port a specific feature commit to a release branch (3) Backport fixes to older versions.

Caution: Cherry-pick creates a NEW commit (different hash). The original commit still exists on its branch.

Find three smallest and three largest values:

function findExtremes(arr) {
  const sorted = [...arr].sort((a, b) => a - b);
  return {
    smallest: sorted.slice(0, 3),
    largest: sorted.slice(-3).reverse()
  };
}

findExtremes([45, 2, 78, 11, 5, 99, 3, 67, 1, 88]);
// { smallest: [1, 2, 3], largest: [99, 88, 78] }

// Without sorting (O(n) — more efficient for large arrays)
function findExtremes(arr) {
  let mins = [Infinity, Infinity, Infinity];
  let maxs = [-Infinity, -Infinity, -Infinity];
  for (const n of arr) {
    if (n < mins[2]) { mins.push(n); mins.sort((a,b) => a-b); mins.pop(); }
    if (n > maxs[2]) { maxs.push(n); maxs.sort((a,b) => b-a); maxs.pop(); }
  }
  return { smallest: mins, largest: maxs };
}

Piping in Node.js connects the output of one stream to the input of another. It handles backpressure automatically.

const fs = require('fs');
const zlib = require('zlib');

// Basic pipe: read file → write file
fs.createReadStream('input.txt').pipe(fs.createWriteStream('output.txt'));

// Chain pipes: read → compress → write
fs.createReadStream('file.txt')
  .pipe(zlib.createGzip())
  .pipe(fs.createWriteStream('file.txt.gz'));

// HTTP response streaming
app.get('/download', (req, res) => {
  const stream = fs.createReadStream('largefile.zip');
  stream.pipe(res); // Stream directly to client
});

// Pipeline (modern — better error handling)
const { pipeline } = require('stream');
pipeline(readStream, transformStream, writeStream, (err) => {
  if (err) console.error('Pipeline failed:', err);
});

pipe() is memory efficient — processes data in chunks instead of loading everything into memory.

Event-driven architecture in Node.js: Components communicate by emitting and listening to events, rather than direct function calls.

const EventEmitter = require('events');

class OrderService extends EventEmitter {
