  }
}

const orderService = new OrderService();

// Different services listen for events
orderService.on('orderCreated', (order) => {
  emailService.sendConfirmation(order); // Send email
});

orderService.on('orderCreated', (order) => {
  inventoryService.reduceStock(order); // Update inventory
});

