Execute operation at a future timestamp sent from frontend:

// Method 1: setTimeout with calculated delay
app.post('/schedule', (req, res) => {
  const { futureTimestamp, action } = req.body;
  const delay = new Date(futureTimestamp) - Date.now();
  if (delay <= 0) return res.status(400).json({ error: 'Timestamp is in the past' });
  setTimeout(() => performAction(action), delay);
  res.json({ message: 'Scheduled' });
});
// Problem: Lost if server restarts!

// Method 2: Job Queue with Bull (production-ready)
const Queue = require('bull');
const scheduledQueue = new Queue('scheduled-tasks', { redis: { host: '127.0.0.1' } });

app.post('/schedule', async (req, res) => {
  const delay = new Date(req.body.futureTimestamp) - Date.now();
  await scheduledQueue.add(req.body.action, { delay });
  res.json({ message: 'Scheduled with persistence' });
});

// Method 3: node-cron or agenda.js for recurring tasks.

Always use a persistent job queue (Bull + Redis) in production — survives server restarts.

