Stop duplicate API calls in Express:

// Method 1: Rate limiting per endpoint
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({ windowMs: 1000, max: 1 }); // 1 request per second
app.post('/api/submit', limiter, handler);

// Method 2: Request deduplication middleware
const pending = new Map();
function dedup(req, res, next) {
  const key = `${req.method}:${req.url}:${JSON.stringify(req.body)}`;
  if (pending.has(key)) return res.status(429).json({ message: 'Request already processing' });
  pending.set(key, true);
  res.on('finish', () => pending.delete(key));
  next();
}

// Method 3: Idempotency key header
app.post('/api/order', async (req, res) => {
  const key = req.headers['x-idempotency-key'];
  const cached = await redis.get(`idem:${key}`);
  if (cached) return res.json(JSON.parse(cached));
  const result = await processOrder(req.body);
  await redis.setex(`idem:${key}`, 3600, JSON.stringify(result));
  res.json(result);
});

