Generate and validate JWT tokens in Node.js:

npm install jsonwebtoken

const jwt = require('jsonwebtoken');
const SECRET = process.env.JWT_SECRET;

// Generate token
function generateToken(user) {
  return jwt.sign(
    { id: user._id, email: user.email, role: user.role },
    SECRET,
    { expiresIn: '24h' }
  );
}

// Login route
app.post('/login', async (req, res) => {
  const user = await User.findOne({ email: req.body.email });
  if (!user || !await bcrypt.compare(req.body.password, user.password)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  const token = generateToken(user);
  res.json({ token, user: { id: user._id, name: user.name } });
});

// Validate token middleware
function authenticate(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Token required' });
  try {
    req.user = jwt.verify(token, SECRET);
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid or expired token' });
  }
}

// Protected route
app.get('/api/profile', authenticate, (req, res) => {
  res.json({ userId: req.user.id });
});

Access Token: Short-lived (15 min to 1 hour). Sent with every API request in the Authorization header. Contains user info. If stolen, limited damage due to short expiry.

Refresh Token: Long-lived (7-30 days). Stored securely (httpOnly cookie). Used ONLY to get a new access token when the current one expires. Never sent with regular API requests.

Flow:
1. Login → Server returns both access token + refresh token
2. Client sends access token with every API request
3. Access token expires → Client sends refresh token to /refresh endpoint
4. Server validates refresh token → Returns new access token
5. Refresh token expires → User must login again

// Refresh endpoint
app.post('/refresh', (req, res) => {
  const refreshToken = req.cookies.refreshToken;
  const decoded = jwt.verify(refreshToken, REFRESH_SECRET);
  const newAccessToken = jwt.sign({ id: decoded.id }, ACCESS_SECRET, { expiresIn: '15m' });
  res.json({ accessToken: newAccessToken });
});

Why two tokens? If access token is stolen, it expires quickly. Refresh token is stored securely and rarely transmitted.

Validate JWT token in Node.js:

const jwt = require('jsonwebtoken');

// Basic validation
function validateToken(token) {
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    return { valid: true, decoded };
  } catch (err) {
    if (err.name === 'TokenExpiredError') return { valid: false, error: 'Token expired' };
    if (err.name === 'JsonWebTokenError') return { valid: false, error: 'Invalid token' };
    return { valid: false, error: 'Token validation failed' };
  }
}

// Express middleware
const authMiddleware = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'No token provided' });
  }
  const token = authHeader.split(' ')[1];
  const { valid, decoded, error } = validateToken(token);
  if (!valid) return res.status(401).json({ error });
  req.user = decoded;
  next();
};

// Role-based authorization
const authorize = (...roles) => (req, res, next) => {
  if (!roles.includes(req.user.role)) return res.status(403).json({ error: 'Forbidden' });
  next();
};

Authorize REST APIs in Node.js — multi-layer approach:

// 1. Authentication middleware (WHO are you?)
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Authentication required' });
  req.user = jwt.verify(token, SECRET);
  next();
};

// 2. Role-based authorization (WHAT can you do?)
const authorize = (...allowedRoles) => (req, res, next) => {
  if (!allowedRoles.includes(req.user.role)) {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }
  next();
};

// 3. Resource-level authorization (IS this yours?)
const authorizeOwner = async (req, res, next) => {
  const resource = await Order.findById(req.params.id);
  if (resource.userId.toString() !== req.user.id) {
    return res.status(403).json({ error: 'Not your resource' });
  }
  next();
};

// Usage
app.get('/api/admin/users', authenticate, authorize('admin'), getUsers);
app.get('/api/orders/:id', authenticate, authorizeOwner, getOrder);
app.delete('/api/posts/:id', authenticate, authorize('admin', 'moderator'), deletePost);

Node.js controller with JWT authentication:

// auth.controller.js
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const User = require('../models/User');

exports.register = async (req, res) => {
  try {
    const { name, email, password } = req.body;
    const exists = await User.findOne({ email });
    if (exists) return res.status(400).json({ error: 'Email already registered' });
    const hashedPassword = await bcrypt.hash(password, 12);
    const user = await User.create({ name, email, password: hashedPassword });
    const token = jwt.sign({ id: user._id, role: user.role }, process.env.JWT_SECRET, { expiresIn: '7d' });
    res.status(201).json({ token, user: { id: user._id, name, email } });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
};

exports.login = async (req, res) => {
  try {
    const { email, password } = req.body;
    const user = await User.findOne({ email }).select('+password');
    if (!user || !await bcrypt.compare(password, user.password)) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }
    const token = jwt.sign({ id: user._id, role: user.role }, process.env.JWT_SECRET, { expiresIn: '7d' });
    res.json({ token, user: { id: user._id, name: user.name } });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
};

exports.getProfile = async (req, res) => {
  const user = await User.findById(req.user.id);
  res.json(user);
};

