Enums in TypeScript define a set of named constants.

// Numeric enum (auto-incremented)
enum Direction { Up, Down, Left, Right } // 0, 1, 2, 3
const dir: Direction = Direction.Up; // 0

// String enum (explicit values)
enum Status {
  Active = 'ACTIVE',
  Inactive = 'INACTIVE',
  Pending = 'PENDING'
}
const status: Status = Status.Active; // 'ACTIVE'

// Use in function
function handleStatus(status: Status): string {
  switch (status) {
    case Status.Active: return 'User is active';
    case Status.Inactive: return 'User is inactive';
    case Status.Pending: return 'Awaiting approval';
  }
}

// const enum (inlined at compile time — more efficient)
const enum Color { Red, Green, Blue }
const c = Color.Red; // Compiled to: const c = 0;

String enums are preferred because they're more readable in debugging and don't have reverse mapping issues.

Union types allow a variable to hold one of several types:

// Basic union
let value: string | number;
value = 'hello'; // OK
value = 42; // OK
value = true; // Error!

// In functions
function formatId(id: string | number): string {
  if (typeof id === 'string') return id.toUpperCase();
  return id.toString().padStart(5, '0');
}
formatId('abc'); // 'ABC'
formatId(42); // '00042'

// Union with literal types
type Status = 'active' | 'inactive' | 'pending';
type HttpMethod = 'GET' | 'POST' | 'PUT' | 'DELETE';

function setStatus(status: Status) { ... }
setStatus('active'); // OK
setStatus('unknown'); // Error!

// Discriminated unions (powerful pattern)
type Shape = 
  | { kind: 'circle'; radius: number }
  | { kind: 'square'; side: number };

function area(shape: Shape): number {
  switch (shape.kind) {
    case 'circle': return Math.PI * shape.radius ** 2;
    case 'square': return shape.side ** 2;
  }
}

An Interface in TypeScript defines the shape/structure of an object — what properties and methods it must have.

