<meta name='viewport' content='width=device-width, initial-scale=1'>
<meta property='og:title' content='Page Title'> (Open Graph for social media)

Angular Meta service: Dynamically set meta tags in SPAs (important for SEO/SSR).
import { Meta, Title } from '@angular/platform-browser';

constructor(private meta: Meta, private title: Title) {}

ngOnInit() {
  this.title.setTitle('React Questions - CrackInterview');
  this.meta.updateTag({ name: 'description', content: '120 React interview questions' });
